/**
 * Background jobs. A job records the request id of the request that enqueued
 * it, and everything a job logs while it runs goes through AppLogger under that
 * same id -- never a fresh one (ruling r-p19bbvh0jhj8xgma).
 */
import { AppLogger, type Sink } from "../platform/logging/AppLogger.ts";

export interface Job {
  readonly kind: string;
  readonly payload: unknown;
}

export interface QueuedJob extends Job {
  readonly id: string;
  readonly requestId: string;
  readonly enqueuedAt: number;
}

export type JobRunner = (job: QueuedJob) => Promise<void> | void;

export class JobQueue {
  readonly #jobs: QueuedJob[] = [];
  readonly #sink: Sink | undefined;
  #next = 1;

  /** A sink can be supplied so a test can observe what jobs log; production uses AppLogger's default. */
  constructor(sink?: Sink) {
    this.#sink = sink;
  }

  enqueue(job: Job, opts: { requestId: string }): string {
    const id = `job-${this.#next++}`;
    this.#jobs.push({ ...job, id, requestId: opts.requestId, enqueuedAt: Date.now() });
    return id;
  }

  get size(): number {
    return this.#jobs.length;
  }

  /**
   * Runs every queued job in order, logging each job's start, success and failure under the
   * request id that enqueued it. A failing job is dropped; the rest still run.
   */
  async run(runner: JobRunner): Promise<{ ran: number; failed: number }> {
    let ran = 0;
    let failed = 0;
    while (this.#jobs.length > 0) {
      const job = this.#jobs.shift()!;
      try {
        // Inside the try on purpose: withRequestId throws on a blank request id, and enqueue
        // does not validate one. Building the logger here turns that into a counted failure
        // instead of a rejection that abandons the jobs still queued behind it.
        const log = AppLogger.withRequestId(job.requestId, this.#sink);
        log.info("job started", { jobId: job.id, kind: job.kind });
        await runner(job);
        log.info("job succeeded", { jobId: job.id, kind: job.kind });
        ran++;
      } catch (err) {
        failed++;
        // Redaction is AppLogger's, not re-implemented here: a secret inside the error
        // message is redacted on the way out.
        this.#logFailure(job, err);
      }
    }
    return { ran, failed };
  }

  /** Reports a failed job, unless the failure was the request id itself -- then there is no id to log under. */
  #logFailure(job: QueuedJob, err: unknown): void {
    const error = err instanceof Error ? err.message : String(err);
    try {
      AppLogger.withRequestId(job.requestId, this.#sink).error("job failed", {
        jobId: job.id,
        kind: job.kind,
        error,
      });
    } catch {
      // A blank request id cannot produce a compliant line, and no line may be written
      // without one (r-eftp2zdb6as643np). The job stays counted as failed.
    }
  }
}
